// extractionListFixture is the rows the shapes below read: four streams (two
// namespaces, two pods each), three routes, a unique id in every line and an
// amount. Over a window of 5m a stream holds several lines of several routes.
func extractionListFixture() (rows []emuRow, end int64) {
	end = int64(1_800_000_000) * 1e9
	streams := []string{`{app="uw",ns="x",pod="a"}`, `{app="uw",ns="x",pod="b"}`, `{app="uw",ns="y",pod="a"}`, `{app="uw",ns="y",pod="c"}`}
	routes := []string{"/x", "/y", "/z"}
	for i := 0; i < 90; i++ {
		route := routes[(i/4)%3]
		amount := float64((i*37)%100 + 1)
		rows = append(rows, emuRow{
			ts:     end - int64(i)*9e9 - 3e8,
			stream: streams[i%4],
			labels: map[string]string{"id": strconv.Itoa(i), "route": route},
			value:  amount,
			msg:    fmt.Sprintf("amount=%v id=%d route=%s", amount, i, route),
		})
	}
	return rows, end
}

// extractionListMode is how a shape is asked: an instant query, a tumbling window
// (the step is the range), a sliding window (the step is shorter).
type extractionListMode struct {
	name   string
	target string
	step   string
}

var extractionListModes = []extractionListMode{
	{"instant", "/loki/api/v1/query?", ""},
	{"tumbling", "/loki/api/v1/query_range?", "300"},
	{"sliding", "/loki/api/v1/query_range?", "60"},
}

// runExtractionListShape sends query through the real handler against the
// emulated VictoriaLogs (v1.52.0) and returns the LogsQL the handler sent to its
// stats endpoints and then to its raw-row endpoint, in order, and the series it
// answered with their values, as text: the series sorted by labels, each as
// `{labels} t=v ...`.
func runExtractionListShape(t *testing.T, query string, mode extractionListMode) (sent []string, answer string) {
	return runExtractionListShapeRows(t, query, mode, nil)
}

// runExtractionListShapeRows is runExtractionListShape over the fixture rows
// changed by edit (nil: unchanged).
func runExtractionListShapeRows(t *testing.T, query string, mode extractionListMode, edit func([]emuRow) []emuRow) (sent []string, answer string) {
	t.Helper()
	rows, end := extractionListFixture()
	if edit != nil {
		rows = edit(rows)
	}
	emu := &vlEmulator{t: t, rows: rows, field: "amount", version: "v1.52.0"}
	backend := httptest.NewServer(emu.handler())
	defer backend.Close()
	p, err := New(Config{BackendURL: backend.URL, Cache: cache.New(60*time.Second, 1000), LogLevel: "error", BackendMinVersion: "v1.40.0", BackendVersionCheckTimeout: time.Second})
	if err != nil {
		t.Fatal(err)
	}
	if err := p.ValidateBackendVersionCompatibility(context.Background()); err != nil {
		t.Fatal(err)
	}
	params := url.Values{"query": {query}}
	if mode.step == "" {
		params.Set("time", strconv.FormatInt(end/1e9, 10))
	} else {
		params.Set("start", strconv.FormatInt(end/1e9-900, 10))
		params.Set("end", strconv.FormatInt(end/1e9, 10))
		params.Set("step", mode.step)
	}
	res := doCompatProxyRequest(p, mode.target+params.Encode(), map[string]string{"X-Scope-OrgID": "0"})
	if res.Code != http.StatusOK {
		return nil, fmt.Sprintf("HTTP %d", res.Code)
	}
	var resp struct {
		Data struct {
			Result []struct {
				Metric map[string]string `json:"metric"`
				Values [][]any           `json:"values"`
				Value  []any             `json:"value"`
			} `json:"result"`
		} `json:"data"`
	}
	if err := json.Unmarshal(res.Body.Bytes(), &resp); err != nil {
		t.Fatal(err)
	}
	var series []string
	for _, s := range resp.Data.Result {
		names := make([]string, 0, len(s.Metric))
		for k, v := range s.Metric {
			names = append(names, k+"="+v)
		}
		sort.Strings(names)
		points := s.Values
		if s.Value != nil {
			points = [][]any{s.Value}
		}
		var b strings.Builder
		b.WriteString("{" + strings.Join(names, ",") + "}")
		for _, point := range points {
			fmt.Fprintf(&b, " %v=%v", point[0], point[1])
		}
		series = append(series, b.String())
	}
	sort.Strings(series)
	for _, path := range []string{"/select/logsql/stats_query", "/select/logsql/stats_query_range", "/select/logsql/query"} {
		sent = append(sent, emu.endpointCalls(path)...)
	}
	return sent, fmt.Sprintf("%d series: %s", len(series), strings.Join(series, "; "))
}

// extractionListShapes are queries that are not a folded `without`, over a
// parser that names the keys it extracts.
var extractionListShapes = []string{
	`sum(max_over_time({app="uw"} | logfmt amount | unwrap amount [5m]))`,
	`avg(avg_over_time({app="uw"} | logfmt amount, route | unwrap amount [5m]))`,
	`max(max_over_time({app="uw"} | logfmt amount, route | unwrap amount [5m]))`,
	`avg by (ns) (avg_over_time({app="uw"} | logfmt amount, route | unwrap amount [5m]))`,
	`count by (ns) (max_over_time({app="uw"} | logfmt amount, route | unwrap amount [5m]))`,
	`sum by (ns) (max_over_time({app="uw"} | logfmt amount, route | unwrap amount [5m]))`,
	`min by (ns) (min_over_time({app="uw"} | logfmt amount, route | unwrap amount [5m]))`,
	`topk(2, max_over_time({app="uw"} | logfmt amount, route | unwrap amount [5m]))`,
	`max_over_time({app="uw"} | logfmt amount, route | unwrap amount [5m])`,
	`sum(rate({app="uw"} | logfmt amount | unwrap amount [5m]))`,
	`sum(rate({app="uw"} | logfmt route [5m]))`,
	`sum by (ns) (rate({app="uw"} | logfmt amount, route | unwrap amount [5m]))`,
	`count_over_time({app="uw"} | logfmt route [5m])`,
	`count by (ns) (count_over_time({app="uw"} | logfmt route [5m]))`,
	`sum(count_over_time({app="uw"} | logfmt route [5m]))`,
	`count by (ns) (rate({app="uw"} | logfmt route [5m]))`,
	`count by (route) (count_over_time({app="uw"} | logfmt route [5m]))`,
	`max by (route) (max_over_time({app="uw"} | logfmt amount, route | unwrap amount [5m]))`,
	// a `without` that is not folded: another operator, or not the outermost aggregation
	`min(sum without (pod) (min_over_time({app="uw"} | logfmt amount | unwrap amount [5m])))`,
	`topk(2, max_over_time({app="uw"} | logfmt amount, route | unwrap amount [5m])) without (pod)`,
	`bottomk(2, max_over_time({app="uw"} | logfmt amount | unwrap amount [5m])) without (pod)`,
	`max(sum without (pod) (max_over_time({app="uw"} | logfmt amount | unwrap amount [5m])))`,
	`sum by (ns) (sum without (pod) (max_over_time({app="uw"} | logfmt amount, route | unwrap amount [5m])))`,
}

// TestExtractionListOutsideWithoutKeepsItsGrouping: the labels an extraction
// list names tell the series of a `without` apart, and only there. Every other
// query after `| logfmt amount, route` is translated and answered as it was
// before: the inner stats group by the line (`_msg`) for an unwrap function and
// by the stream for a rate, whatever the outer aggregation, on an instant query,
// a tumbling window and a sliding one. The grouping and the answers are the
// ones origin/main produced (the golden table); the answers are not Loki's
// (semantics/unwrap-extraction-list-series-identity, open).
// The three `without` nested under another aggregation (min, max and sum by (ns)
// over a `sum without`) are the exception: a sum, avg, min, max or count over a
// `without` is folded level by level, innermost first, so their instant and
// tumbling answers are Loki's (per-ns sums, then the minimum, the maximum, or the
// sum by ns of them), and a sliding one is that fold of the sliding `sum without`
// answer (semantics/nested-aggregation-outer-by-native-routes).
// The unwrap sum, avg, min and max over time answers are the ones origin/main
// produced, preceded by one more sample at `start`: the old values sit one step
// later, the last one on `end` (semantics/unwrap-range-last-point).
//
// conformance: semantics/unwrap-extraction-list-series-identity, metric-series-identity
func TestExtractionListOutsideWithoutKeepsItsGrouping(t *testing.T) {
	for _, query := range extractionListShapes {
		for _, mode := range extractionListModes {
			t.Run(mode.name+"/"+query, func(t *testing.T) {
				sent, answer := runExtractionListShape(t, query, mode)
				got := extractionListGolden{Sent: sent, Answer: answer}
				want, ok := extractionListGoldens[mode.name+"|"+query]
				if !ok {
					t.Fatalf("no golden for %s|%s; got %s", mode.name, query, got.literal())
				}
				if got.literal() != want.literal() {
					t.Fatalf("differs from origin/main\n got %s\nwant %s", got.literal(), want.literal())
				}
			})
		}
	}
}

type extractionListGolden struct {
	Sent   []string
	Answer string
}

func (g extractionListGolden) literal() string {
	return fmt.Sprintf("{Sent: %#v, Answer: %q}", g.Sent, g.Answer)
}

